**Metaclass:** Sınıfları üreten sınıflardır. `type` Python'un default metaclass'ıdır.

```python
# Basit metaclass
class MyMeta(type):
    def __new__(mcs, name, bases, namespace):
        cls = super().__new__(mcs, name, bases, namespace)
        print(f"Sınıf oluşturuldu: {name}")
        return cls

class MyClass(metaclass=MyMeta):  # → "Sınıf oluşturuldu: MyClass"
    pass
```

**ORM Metaclass Örneği:**

```python
class Field:
    def __init__(self, field_type, primary_key=False, max_length=None):
        self.field_type = field_type
        self.primary_key = primary_key
        self.max_length = max_length
        self.name = None  # metaclass tarafından set edilir

class CharField(Field):
    def __init__(self, max_length=255, **kwargs):
        super().__init__('VARCHAR', max_length=max_length, **kwargs)

class IntegerField(Field):
    def __init__(self, **kwargs):
        super().__init__('INTEGER', **kwargs)

class ModelMeta(type):
    def __new__(mcs, name, bases, namespace):
        fields = {}
        for key, val in namespace.items():
            if isinstance(val, Field):
                val.name = key
                fields[key] = val

        namespace['_fields'] = fields
        namespace['_table_name'] = name.lower() + 's'

        cls = super().__new__(mcs, name, bases, namespace)
        return cls

class Model(metaclass=ModelMeta):
    def __init__(self, **kwargs):
        for name, field in self._fields.items():
            setattr(self, name, kwargs.get(name))

    def save(self):
        columns = ', '.join(self._fields.keys())
        values = ', '.join(f"'{getattr(self, f)}'" for f in self._fields)
        return f"INSERT INTO {self._table_name} ({columns}) VALUES ({values})"

    @classmethod
    def create_table(cls):
        cols = []
        for name, field in cls._fields.items():
            col = f"{name} {field.field_type}"
            if field.max_length:
                col = f"{name} {field.field_type}({field.max_length})"
            if field.primary_key:
                col += " PRIMARY KEY"
            cols.append(col)
        return f"CREATE TABLE {cls._table_name} ({', '.join(cols)})"

# Kullanım
class User(Model):
    id = IntegerField(primary_key=True)
    name = CharField(max_length=100)
    email = CharField(max_length=200)

print(User.create_table())
# CREATE TABLE users (id INTEGER PRIMARY KEY, name VARCHAR(100), email VARCHAR(200))

user = User(id=1, name='Ali', email='ali@test.com')
print(user.save())
# INSERT INTO users (id, name, email) VALUES ('1', 'Ali', 'ali@test.com')
```

**Metaclass ne zaman kullanılır:**
- ORM framework'leri (Django)
- API framework'leri (Django REST)
- Singleton pattern
- Otomatik kayıt (registry pattern)
- Sınıf validasyonu
